package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                        // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.New(0, 0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.New(0, 0)   // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0                              // PIC 9(5) len=5 = 0
var WsPrinEd string                                // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string                                 // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string                               // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

var loanFile *os.File
var loanReader *bufio.Reader

func storeDecimal(v decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	// truncate toward zero to scale (if needed) then keep low-order digits
	v = v.Truncate(scale)
	// low-order digit truncation: mod 10^(intDigits+scale) on scaled integer
	fracPow := decimal.New(1, scale) // 10^scale
	intPow := decimal.New(1, intDigits)
	modBase := intPow.Mul(fracPow) // 10^(intDigits+scale) ??? Actually 10^intDigits * 10^scale = 10^(intDigits+scale)
	// scaled = v * 10^scale (integer)
	scaled := v.Mul(fracPow).Truncate(0)
	// keep sign
	sign := 1
	if scaled.IsNegative() {
		sign = -1
		scaled = scaled.Abs()
	}
	// mod
	if modBase.IsZero() == false {
		scaled = scaled.Mod(modBase)
	}
	if sign == -1 {
		scaled = scaled.Neg()
	}
	// back
	return scaled.Div(fracPow).Truncate(scale)
}

func formatEdited(v decimal.Decimal, picture string) string {
	// split picture
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx == -1 {
		intPic = picture
		fracPic = ""
	} else {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}

	// handle sign - we only handle positive for this program, but keep abs for formatting
	isNeg := v.IsNegative()
	absV := v.Abs()
	// trunc to fracDigits scale for display (value already at correct scale)
	absV = absV.Truncate(int32(fracDigits))

	// compute integer mod and fraction to drop high-order digits
	// scaled = absV * 10^fracDigits
	var scaled decimal.Decimal
	if fracDigits > 0 {
		scaled = absV.Shift(int32(fracDigits)).Truncate(0)
	} else {
		scaled = absV.Truncate(0)
	}
	// mod base = 10^(intDigits+fracDigits)
	modBase := decimal.New(1, int32(intDigits+fracDigits))
	// only mod if overflow
	if intDigits+fracDigits > 0 {
		// if scaled >= modBase, keep low-order digits
		if scaled.Cmp(modBase) >= 0 {
			scaled = scaled.Mod(modBase)
		}
	}
	// create zero padded digit string of length intDigits+fracDigits
	var scaledStr string
	// scaled is integer decimal, get string without exponent
	// Use StringFixed(0) to get plain
	scaledStr = scaled.StringFixed(0)
	// remove sign if any (should be positive)
	if strings.HasPrefix(scaledStr, "-") {
		scaledStr = scaledStr[1:]
	}
	// remove decimal point if any
	if idx := strings.Index(scaledStr, "."); idx != -1 {
		scaledStr = scaledStr[:idx]
	}
	need := intDigits + fracDigits
	if len(scaledStr) < need {
		scaledStr = strings.Repeat("0", need-len(scaledStr)) + scaledStr
	} else if len(scaledStr) > need {
		scaledStr = scaledStr[len(scaledStr)-need:]
	}
	intStr := ""
	fracStr := ""
	if intDigits > 0 {
		intStr = scaledStr[:intDigits]
	}
	if fracDigits > 0 {
		fracStr = scaledStr[intDigits:]
	}

	// Build integer part result with digits placed
	intResult := []byte(intPic) // will overwrite Z/9 with digits
	// placeholder order
	// find first non-zero pos in intStr
	firstNonZeroPos := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZeroPos = i
			break
		}
	}
	// Determine which placeholder positions are suppressed
	// Map placeholder order index -> suppressed bool
	placeholderSuppressed := make([]bool, intDigits)
	for p := 0; p < intDigits; p++ {
		// need picture char for this placeholder: we need to know if Z or 9
		// Find the p-th placeholder char in intPic
		cnt := -1
		var picChar byte
		for j := 0; j < len(intPic); j++ {
			c := intPic[j]
			if c == 'Z' || c == '9' {
				cnt++
				if cnt == p {
					picChar = c
					break
				}
			}
		}
		if picChar == '9' {
			placeholderSuppressed[p] = false
		} else { // Z
			if firstNonZeroPos == -1 {
				placeholderSuppressed[p] = true
			} else if p < firstNonZeroPos {
				placeholderSuppressed[p] = true
			} else {
				placeholderSuppressed[p] = false
			}
		}
	}

	// Now fill intResult with digits and handle commas suppression
	// We need to know for each comma whether left side all suppressed
	// Compute for each position the placeholder index of placeholders before it
	// Walk left to right
	placeholderIdx := 0 // index of next placeholder to fill in intStr
	// First fill digits into intResult placeholders
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			// place digit
			var d byte
			if placeholderIdx < len(intStr) {
				d = intStr[placeholderIdx]
			} else {
				d = '0'
			}
			if placeholderSuppressed[placeholderIdx] {
				intResult[i] = ' '
			} else {
				intResult[i] = d
			}
			placeholderIdx++
		} else if c == ',' {
			// determine if comma should be suppressed:
			// if all placeholders before this comma are suppressed, suppress comma
			// count placeholders before i
			placeholdersBefore := 0
			suppressedBefore := 0
			cnt := 0
			for j := 0; j < i; j++ {
				if intPic[j] == 'Z' || intPic[j] == '9' {
					placeholdersBefore++
					// find its placeholder index = cnt
					if placeholderSuppressed[cnt] {
						suppressedBefore++
					}
					cnt++
				}
			}
			if placeholdersBefore > 0 && suppressedBefore == placeholdersBefore {
				// check if there is at least one non-suppressed after? Actually if all before suppressed,
				// comma is inside suppressed zone -> space, regardless of after
				intResult[i] = ' '
			} else {
				intResult[i] = ','
			}
		} else {
			intResult[i] = c
		}
	}

	// Build fractional part result
	var fracResult []byte
	if fracDigits > 0 {
		fracResult = []byte(fracPic)
		for i := 0; i < len(fracPic); i++ {
			c := fracPic[i]
			if c == 'Z' || c == '9' {
				// there is only 9 in spec
				// map to fracStr sequentially
				// placeholder order for fraction is direct
				// count placeholders up to i
				cnt := 0
				for j := 0; j < i; j++ {
					if fracPic[j] == 'Z' || fracPic[j] == '9' {
						cnt++
					}
				}
				// cnt is index in fracStr
				if cnt < len(fracStr) {
					fracResult[i] = fracStr[cnt]
				} else {
					fracResult[i] = '0'
				}
			} else {
				fracResult[i] = c
			}
		}
	}

	var final string
	if dotIdx != -1 {
		final = string(intResult) + "." + string(fracResult)
	} else {
		final = string(intResult)
	}
	// handle negative sign: if original negative, put '-' at last suppressed space? For this program no negatives needed.
	if isNeg {
		// place minus in front of first non-space digit
		// find first non-space in final
		for i, ch := range final {
			if ch != ' ' && ch != ',' && ch != '.' {
				// replace preceding space with '-' if possible, else prepend
				if i > 0 && final[i-1] == ' ' {
					b := []byte(final)
					b[i-1] = '-'
					final = string(b)
				} else {
					final = "-" + final
				}
				break
			}
		}
	}
	return final
}

func parseDecimalField(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// s contains digits only, possibly with sign
	// handle sign
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	// remove spaces
	s = strings.ReplaceAll(s, " ", "")
	if s == "" {
		return decimal.New(0, 0)
	}
	// parse as integer
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback to 0
		return decimal.New(0, 0)
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parseIntField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	fmt.Sscanf(s, "%d", &v)
	return v
}

func readPara() {
	line, err := loanReader.ReadString('\n')
	if err != nil {
		// if we got some data before EOF, process it; otherwise set EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// partial line without newline at EOF still counts
	}
	// Remove trailing \r and \n
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces on right to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	loanRec.LrAcct = line[0:6]
	loanRec.LrPrincipal = parseDecimalField(line[6:15], 2)
	loanRec.LrRate = parseDecimalField(line[15:19], 2)
	loanRec.LrYears = parseIntField(line[19:21])
}

func processPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	yearsDec := decimal.NewFromInt(loanRec.LrYears)
	calc := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(yearsDec).Shift(-2)
	rounded := calc.Round(2)
	WsInterest = storeDecimal(rounded, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = storeDecimal(WsTotal, 11, 2)

	WsCount++
	// keep low-order digits for 9(5)
	if WsCount >= 100000 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	// LR-ACCT is X(6) exactly 6 chars
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	// WS-COUNT is PIC 9(5) zero padded
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func mainPara() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer loanFile.Close()
	loanReader = bufio.NewReader(loanFile)

	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	loanFile.Close()
	summaryPara()
}

func main() {
	mainPara()
}
